import { useEffect, useRef, useState } from 'react';
import { forceSimulation, forceLink, forceManyBody, forceX, forceY, forceCollide } from 'd3-force';
import './NotesGraph.css';

// graph.json is generated by the milynotes build, so new notes and links show up here on their own.
const NOTES_URL = (import.meta.env.VITE_NOTES_URL || 'https://notes.ameliali.com').replace(/\/$/, '');

// Muted tones that sit next to the site's #473C35 brown.
const PALETTE = ['#8C6A54', '#8FA37A', '#C9A15F', '#7D8FA8', '#C08484', '#9C89B8', '#6E9C9A', '#B58A6A'];

const LINK_RGB = '71, 60, 53';
const LABEL_COLOR = '#473C35';
const MIN_ZOOM = 0.25;
const MAX_ZOOM = 6;
const DIM = 0.15;

function nodeRadius(degree) {
  return 3.5 + Math.sqrt(degree) * 2;
}

function clamp(v, lo, hi) {
  return Math.min(hi, Math.max(lo, v));
}

function NotesGraph() {
  const cardRef = useRef(null);
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const controlsRef = useRef({});
  const [graph, setGraph] = useState(null);
  const [error, setError] = useState(false);
  const [tooltip, setTooltip] = useState(null);
  const [active, setActive] = useState(false);
  const [nudge, setNudge] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showControlsHint, setShowControlsHint] = useState(false);

  const isCoarse = typeof window !== 'undefined' && window.matchMedia('(pointer: coarse)').matches;
  const canFullscreen = typeof document !== 'undefined' && !!document.documentElement.requestFullscreen;

  useEffect(() => {
    let cancelled = false;
    fetch(`${NOTES_URL}/graph.json`)
      .then((res) => {
        if (!res.ok) throw new Error(res.statusText);
        return res.json();
      })
      .then((data) => {
        if (cancelled) return;
        const colors = new Map();
        data.nodes.forEach((n) => {
          if (!colors.has(n.categoryId)) colors.set(n.categoryId, PALETTE[colors.size % PALETTE.length]);
        });
        setGraph({ data, colors });
      })
      .catch(() => !cancelled && setError(true));
    return () => {
      cancelled = true;
    };
  }, []);

  // Show how to drive the graph for a few seconds after it's first grabbed.
  useEffect(() => {
    if (!active) return undefined;
    setShowControlsHint(true);
    const t = setTimeout(() => setShowControlsHint(false), 3500);
    return () => clearTimeout(t);
  }, [active]);

  useEffect(() => {
    const onChange = () => setIsFullscreen(document.fullscreenElement === cardRef.current);
    document.addEventListener('fullscreenchange', onChange);
    return () => document.removeEventListener('fullscreenchange', onChange);
  }, []);

  useEffect(() => {
    if (!graph) return undefined;
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    const ctx = canvas.getContext('2d');
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    const nodes = graph.data.nodes.map((n) => ({ ...n, degree: 0, vis: 1, color: graph.colors.get(n.categoryId) }));
    const byId = new Map(nodes.map((n) => [n.id, n]));
    const links = graph.data.links
      .filter((l) => byId.has(l.source) && byId.has(l.target))
      .map((l) => ({ source: byId.get(l.source), target: byId.get(l.target), vis: 0 }));
    const neighbors = new Map(nodes.map((n) => [n, new Set()]));
    links.forEach(({ source, target }) => {
      source.degree += 1;
      target.degree += 1;
      neighbors.get(source).add(target);
      neighbors.get(target).add(source);
    });

    const simulation = forceSimulation(nodes)
      .force('link', forceLink(links).distance(55).strength(0.6))
      .force('charge', forceManyBody().strength(-90))
      .force('x', forceX(0).strength(0.06))
      .force('y', forceY(0).strength(0.08))
      .force('collide', forceCollide((n) => nodeRadius(n.degree) + 3))
      .stop();
    // Settle the layout up front so the graph doesn't explode out of the middle on load.
    for (let i = 0; i < 300; i += 1) simulation.tick();

    let width = 0;
    let height = 0;
    // screen = rotate(a) * scale(k) * graphPoint + (x, y)
    const view = { k: 1, x: 0, y: 0, a: 0 };
    let anim = null;
    let hovered = null;
    let selected = null; // touch: first tap selects, second tap opens
    let userMoved = false;
    let isActive = false;
    let raf = 0;
    let nudgeTimer = 0;
    let mouse = null; // last mouse position over the canvas, so hover stays right while the graph moves

    const pointers = new Map();
    let gesture = null;

    function scaledRadius(n) {
      return nodeRadius(n.degree) * clamp(view.k, 0.5, 3);
    }

    function toScreen(gx, gy) {
      const c = Math.cos(view.a);
      const s = Math.sin(view.a);
      return [view.x + view.k * (c * gx - s * gy), view.y + view.k * (s * gx + c * gy)];
    }

    function toGraph(sx, sy) {
      const dx = (sx - view.x) / view.k;
      const dy = (sy - view.y) / view.k;
      const c = Math.cos(-view.a);
      const s = Math.sin(-view.a);
      return [c * dx - s * dy, s * dx + c * dy];
    }

    /** Move the view so graph point (gx, gy) sits at screen point (sx, sy). */
    function pin(gx, gy, sx, sy) {
      const c = Math.cos(view.a);
      const s = Math.sin(view.a);
      view.x = sx - view.k * (c * gx - s * gy);
      view.y = sy - view.k * (s * gx + c * gy);
    }

    function localPoint(e) {
      const rect = canvas.getBoundingClientRect();
      return [e.clientX - rect.left, e.clientY - rect.top];
    }

    function fitTarget() {
      const pad = 40;
      const xs = nodes.map((n) => n.x);
      const ys = nodes.map((n) => n.y);
      const minX = Math.min(...xs);
      const maxX = Math.max(...xs);
      const minY = Math.min(...ys);
      const maxY = Math.max(...ys);
      const k = clamp(Math.min((width - pad * 2) / (maxX - minX || 1), (height - pad * 2) / (maxY - minY || 1)), MIN_ZOOM, 2.2);
      return { k, a: 0, x: width / 2 - ((minX + maxX) / 2) * k, y: height / 2 - ((minY + maxY) / 2) * k };
    }

    function zoomAt(factor, sx, sy) {
      const from = anim?.type === 'zoom' ? anim.tk : view.k;
      const [gx, gy] = toGraph(sx, sy);
      anim = { type: 'zoom', tk: clamp(from * factor, MIN_ZOOM, MAX_ZOOM), sx, sy, gx, gy };
      userMoved = true;
      kick();
    }

    function fit(animate = true) {
      const to = fitTarget();
      if (!animate || reduceMotion) {
        Object.assign(view, to);
        anim = null;
      } else {
        // Unwind rotation the short way round.
        view.a = (((view.a % (Math.PI * 2)) + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
        anim = { type: 'fit', to };
      }
      userMoved = false;
      kick();
    }

    function setActiveState(next) {
      if (isActive === next) return;
      isActive = next;
      canvas.style.touchAction = next ? 'none' : 'pan-y';
      setActive(next);
    }

    function focusNode() {
      return hovered || selected;
    }

    function step() {
      raf = 0;
      let busy = false;

      if (simulation.alpha() > simulation.alphaMin() || gesture?.type === 'node') {
        simulation.tick();
        busy = true;
      }

      if (anim?.type === 'zoom') {
        view.k += (anim.tk - view.k) * (reduceMotion ? 1 : 0.22);
        if (Math.abs(anim.tk - view.k) < anim.tk * 0.002) view.k = anim.tk;
        pin(anim.gx, anim.gy, anim.sx, anim.sy);
        if (view.k === anim.tk) anim = null;
        busy = true;
      } else if (anim?.type === 'fit') {
        const { to } = anim;
        const t = 0.16;
        view.k += (to.k - view.k) * t;
        view.x += (to.x - view.x) * t;
        view.y += (to.y - view.y) * t;
        view.a += (to.a - view.a) * t;
        if (Math.abs(to.k - view.k) < 0.002 && Math.abs(to.x - view.x) < 0.5 && Math.abs(to.y - view.y) < 0.5 && Math.abs(view.a) < 0.002) {
          Object.assign(view, to);
          anim = null;
        }
        busy = true;
      }

      // Fade nodes and lines in and out on hover, the way Obsidian does.
      const focus = focusNode();
      const fade = reduceMotion ? 1 : 0.2;
      nodes.forEach((n) => {
        const goal = !focus || n === focus || neighbors.get(focus).has(n) ? 1 : DIM;
        if (Math.abs(goal - n.vis) > 0.01) {
          n.vis += (goal - n.vis) * fade;
          busy = true;
        } else n.vis = goal;
      });
      // l.vis: 0 = resting, 1 = touches the focused note, -1 = faded out.
      links.forEach((l) => {
        const goal = !focus ? 0 : l.source === focus || l.target === focus ? 1 : -1;
        if (Math.abs(goal - l.vis) > 0.01) {
          l.vis += (goal - l.vis) * fade;
          busy = true;
        } else l.vis = goal;
      });

      if (busy && !gesture && mouse) {
        const n = nodeAt(mouse[0], mouse[1], 4);
        if (n !== hovered) {
          hovered = n;
          canvas.classList.toggle('notes-graph-canvas--pointer', !!n);
        }
      }
      if (busy && focusNode() && !(gesture && (gesture.type === 'pinch' || gesture.type === 'rotate'))) showTooltip(focusNode());
      else if (busy && !focusNode()) setTooltip(null);

      draw();
      if (busy) raf = requestAnimationFrame(step);
    }

    function kick() {
      if (!raf) raf = requestAnimationFrame(step);
    }

    function draw() {
      const dpr = window.devicePixelRatio || 1;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, width, height);

      const focus = focusNode();
      const pos = new Map(nodes.map((n) => [n, toScreen(n.x, n.y)]));

      ctx.lineWidth = clamp(view.k, 0.6, 1.6);
      links.forEach((l) => {
        const [x1, y1] = pos.get(l.source);
        const [x2, y2] = pos.get(l.target);
        const lit = Math.max(0, l.vis);
        if (lit > 0.05 && focus) {
          ctx.strokeStyle = focus.color;
          ctx.globalAlpha = 0.25 + lit * 0.6;
        } else {
          ctx.strokeStyle = `rgb(${LINK_RGB})`;
          ctx.globalAlpha = l.vis >= 0 ? 0.18 : 0.18 * (1 + l.vis * (1 - DIM));
        }
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
      });

      nodes.forEach((n) => {
        const [x, y] = pos.get(n);
        ctx.globalAlpha = n.vis;
        ctx.fillStyle = n.color;
        ctx.beginPath();
        ctx.arc(x, y, scaledRadius(n), 0, Math.PI * 2);
        ctx.fill();
        if (n === focus) {
          ctx.globalAlpha = 1;
          ctx.strokeStyle = LABEL_COLOR;
          ctx.lineWidth = 1.5;
          ctx.stroke();
        }
      });

      // Labels fade in as you zoom; the focused note's neighborhood is always labeled.
      const zoomFade = clamp((view.k - 1.1) / 0.6, 0, 1);
      ctx.font = `${11 * clamp(Math.sqrt(view.k), 0.9, 1.5)}px Arial`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.lineJoin = 'round';
      nodes.forEach((n) => {
        const near = focus && (n === focus || neighbors.get(focus).has(n));
        const alpha = near ? 1 : zoomFade * n.vis;
        if (alpha < 0.03) return;
        const [x, y] = pos.get(n);
        const ty = y + scaledRadius(n) + 4;
        ctx.globalAlpha = alpha;
        ctx.lineWidth = 3;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
        ctx.strokeText(n.title, x, ty);
        ctx.fillStyle = LABEL_COLOR;
        ctx.fillText(n.title, x, ty);
      });
      ctx.globalAlpha = 1;
    }

    function resize() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      if (!userMoved) fit(false);
      draw();
    }

    function nodeAt(sx, sy, slop) {
      let best = null;
      let bestDist = Infinity;
      nodes.forEach((n) => {
        const [x, y] = toScreen(n.x, n.y);
        const d = Math.hypot(x - sx, y - sy);
        if (d < scaledRadius(n) + slop && d < bestDist) {
          best = n;
          bestDist = d;
        }
      });
      return best;
    }

    function showTooltip(n) {
      if (!n) return setTooltip(null);
      const [x, y] = toScreen(n.x, n.y);
      // Anchor near the edges so the tooltip stays inside the card.
      const align = x < width * 0.25 ? 'left' : x > width * 0.75 ? 'right' : 'center';
      setTooltip({ node: n, x, y: y - scaledRadius(n), align });
    }

    function openNote(n) {
      window.open(`${NOTES_URL}${n.url}`, '_blank', 'noopener');
    }

    function twoFingerState() {
      const [p1, p2] = [...pointers.values()];
      return {
        cx: (p1.x + p2.x) / 2,
        cy: (p1.y + p2.y) / 2,
        dist: Math.hypot(p2.x - p1.x, p2.y - p1.y) || 1,
        angle: Math.atan2(p2.y - p1.y, p2.x - p1.x),
      };
    }

    function releaseNode() {
      const n = gesture.node;
      n.fx = null;
      n.fy = null;
      simulation.alphaTarget(0);
    }

    function selectForTouch(n) {
      selected = n;
      hovered = null;
      showTooltip(n);
      kick();
    }

    function onPointerDown(e) {
      const [sx, sy] = localPoint(e);
      const touch = e.pointerType === 'touch';
      pointers.set(e.pointerId, { x: sx, y: sy });

      // On phones the graph only grabs gestures once it's been tapped, so the page still scrolls.
      if (touch && !isActive) {
        gesture = { type: 'tap', sx, sy, moved: false, node: nodeAt(sx, sy, 12), touch };
        return;
      }
      if (!touch) setActiveState(true);
      try {
        canvas.setPointerCapture(e.pointerId);
      } catch {
        // Pointer already gone; nothing to capture.
      }
      anim = null;

      if (pointers.size === 2) {
        if (gesture?.type === 'node') releaseNode();
        const start = twoFingerState();
        const [gx, gy] = toGraph(start.cx, start.cy);
        gesture = { type: 'pinch', start, k: view.k, a: view.a, gx, gy };
        return;
      }

      const n = nodeAt(sx, sy, touch ? 12 : 4);
      if (n) {
        const [gx, gy] = toGraph(sx, sy);
        gesture = { type: 'node', node: n, sx, sy, moved: false, offX: n.x - gx, offY: n.y - gy, touch };
        n.fx = n.x;
        n.fy = n.y;
        hovered = n;
        showTooltip(n);
      } else if (e.shiftKey || e.altKey || e.button === 2) {
        const [gx, gy] = toGraph(width / 2, height / 2);
        gesture = { type: 'rotate', sx, sy, a: view.a, cx: width / 2, cy: height / 2, gx, gy, moved: false };
      } else {
        gesture = { type: 'pan', sx, sy, x: view.x, y: view.y, moved: false, touch };
      }
      kick();
    }

    function onPointerMove(e) {
      const [sx, sy] = localPoint(e);
      if (pointers.has(e.pointerId)) pointers.set(e.pointerId, { x: sx, y: sy });

      if (e.pointerType !== 'touch') mouse = [sx, sy];
      if (!gesture) {
        if (e.pointerType === 'touch') return;
        const n = nodeAt(sx, sy, 4);
        if (n !== hovered) {
          hovered = n;
          canvas.classList.toggle('notes-graph-canvas--pointer', !!n);
          kick();
        }
        showTooltip(n);
        return;
      }

      if (gesture.type === 'pinch') {
        if (pointers.size < 2) return;
        const now = twoFingerState();
        view.k = clamp(gesture.k * (now.dist / gesture.start.dist), MIN_ZOOM, MAX_ZOOM);
        view.a = gesture.a + (now.angle - gesture.start.angle);
        pin(gesture.gx, gesture.gy, now.cx, now.cy);
        userMoved = true;
        setTooltip(null);
        kick();
        return;
      }

      if (Math.hypot(sx - gesture.sx, sy - gesture.sy) > 4) gesture.moved = true;
      if (!gesture.moved || gesture.type === 'tap') return;

      if (gesture.type === 'node') {
        const [gx, gy] = toGraph(sx, sy);
        gesture.node.fx = gx + gesture.offX;
        gesture.node.fy = gy + gesture.offY;
        simulation.alphaTarget(0.3);
        if (simulation.alpha() < 0.3) simulation.alpha(0.3);
        showTooltip(gesture.node);
      } else if (gesture.type === 'pan') {
        view.x = gesture.x + (sx - gesture.sx);
        view.y = gesture.y + (sy - gesture.sy);
        userMoved = true;
        if (selected) showTooltip(selected);
      } else if (gesture.type === 'rotate') {
        const start = Math.atan2(gesture.sy - gesture.cy, gesture.sx - gesture.cx);
        const now = Math.atan2(sy - gesture.cy, sx - gesture.cx);
        view.a = gesture.a + (now - start);
        pin(gesture.gx, gesture.gy, gesture.cx, gesture.cy);
        userMoved = true;
        setTooltip(null);
      }
      kick();
    }

    function onPointerUp(e) {
      pointers.delete(e.pointerId);
      const g = gesture;
      if (!g) return;

      if (g.type === 'pinch') {
        // Lifting one finger of a pinch hands over to a one-finger pan.
        if (pointers.size === 1) {
          const [p] = [...pointers.values()];
          gesture = { type: 'pan', sx: p.x, sy: p.y, x: view.x, y: view.y, moved: true, touch: true };
        } else gesture = null;
        return;
      }
      gesture = null;
      if (g.type === 'node') releaseNode();

      if (g.moved) {
        if (g.touch) {
          hovered = null;
          showTooltip(selected);
        }
        kick();
        return;
      }

      if (g.type === 'tap') {
        setActiveState(true);
        selectForTouch(g.node);
      } else if (g.touch) {
        if (g.node && g.node === selected) openNote(g.node);
        else selectForTouch(g.node || null);
      } else if (g.type === 'node') {
        openNote(g.node);
      }
    }

    function onPointerCancel(e) {
      pointers.delete(e.pointerId);
      if (gesture?.type === 'node') releaseNode();
      gesture = null;
    }

    function onPointerLeave(e) {
      if (e.pointerType === 'touch' || gesture) return;
      mouse = null;
      hovered = null;
      canvas.classList.remove('notes-graph-canvas--pointer');
      setTooltip(null);
      kick();
    }

    function onWheel(e) {
      const pinch = e.ctrlKey || e.metaKey;
      if (!isActive && !pinch) {
        // Leave normal page scrolling alone until the graph has been clicked.
        clearTimeout(nudgeTimer);
        setNudge(true);
        nudgeTimer = setTimeout(() => setNudge(false), 1400);
        return;
      }
      e.preventDefault();
      const [sx, sy] = localPoint(e);
      const delta = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
      mouse = [sx, sy];
      zoomAt(Math.exp(-delta * (pinch ? 0.01 : 0.0022)), sx, sy);
    }

    function onContextMenu(e) {
      e.preventDefault();
    }

    function onDocPointerDown(e) {
      if (cardRef.current?.contains(e.target)) return;
      setActiveState(false);
      if (selected) selectForTouch(null);
    }

    function onKey(e) {
      if (isActive && e.key === 'Escape') setActiveState(false);
    }

    const observer = new ResizeObserver(resize);
    observer.observe(wrap);
    resize();

    canvas.style.touchAction = 'pan-y';
    canvas.addEventListener('pointerdown', onPointerDown);
    canvas.addEventListener('pointermove', onPointerMove);
    canvas.addEventListener('pointerup', onPointerUp);
    canvas.addEventListener('pointercancel', onPointerCancel);
    canvas.addEventListener('pointerleave', onPointerLeave);
    canvas.addEventListener('wheel', onWheel, { passive: false });
    canvas.addEventListener('contextmenu', onContextMenu);
    document.addEventListener('pointerdown', onDocPointerDown);
    document.addEventListener('keydown', onKey);

    controlsRef.current = {
      zoomIn: () => zoomAt(1.4, width / 2, height / 2),
      zoomOut: () => zoomAt(1 / 1.4, width / 2, height / 2),
      fit: () => fit(true),
    };

    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(nudgeTimer);
      simulation.stop();
      observer.disconnect();
      canvas.removeEventListener('pointerdown', onPointerDown);
      canvas.removeEventListener('pointermove', onPointerMove);
      canvas.removeEventListener('pointerup', onPointerUp);
      canvas.removeEventListener('pointercancel', onPointerCancel);
      canvas.removeEventListener('pointerleave', onPointerLeave);
      canvas.removeEventListener('wheel', onWheel);
      canvas.removeEventListener('contextmenu', onContextMenu);
      document.removeEventListener('pointerdown', onDocPointerDown);
      document.removeEventListener('keydown', onKey);
      controlsRef.current = {};
    };
  }, [graph]);

  function toggleFullscreen() {
    if (document.fullscreenElement) document.exitFullscreen();
    else cardRef.current?.requestFullscreen();
  }

  const noteCount = graph?.data.nodes.length ?? 0;
  const linkCount = graph?.data.links.length ?? 0;

  let hint = isCoarse ? 'Tap the graph to explore' : 'Click the graph to zoom with scroll';
  if (active) hint = isCoarse ? 'Drag to pan · pinch to zoom & rotate' : 'Scroll to zoom · drag to pan · shift + drag to rotate';

  return (
    <div className="notes-graph-section">
      <div className="notes-graph-title-wrapper">
        <h2 className="notes-graph-title">Notes</h2>
        <p className="notes-graph-subtitle">
          Notes from{' '}
          <a href={NOTES_URL} target="_blank" rel="noopener noreferrer" className="notes-graph-link">
            notes.ameliali.com
          </a>
          , in graph view
        </p>
      </div>

      <div className={`notes-graph-card ${active ? 'notes-graph-card--active' : ''}`} ref={cardRef}>
        <div className="notes-graph-canvas-wrap" ref={wrapRef}>
          {graph && <canvas ref={canvasRef} className="notes-graph-canvas" aria-label={`Graph of ${noteCount} notes and the links between them`} role="img" />}
          {!graph && !error && <p className="notes-graph-status">Loading notes…</p>}
          {error && (
            <p className="notes-graph-status">
              <span>
                Couldn&apos;t load the graph right now. The notes are still{' '}
                <a href={NOTES_URL} target="_blank" rel="noopener noreferrer" className="notes-graph-link">
                  over here
                </a>
                .
              </span>
            </p>
          )}

          {tooltip && (
            <div className={`notes-graph-tooltip notes-graph-tooltip--${tooltip.align}`} style={{ left: tooltip.x, top: tooltip.y }}>
              <strong>{tooltip.node.title}</strong>
              <span>
                {tooltip.node.categoryName} · {tooltip.node.degree} {tooltip.node.degree === 1 ? 'link' : 'links'}
              </span>
              {isCoarse && <span>Tap again to open</span>}
            </div>
          )}

          {graph && (
            <div className="notes-graph-controls">
              <button type="button" className="notes-graph-control" onClick={() => controlsRef.current.zoomIn?.()} aria-label="Zoom in" title="Zoom in">
                <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round">
                  <path d="M8 3v10M3 8h10" />
                </svg>
              </button>
              <button type="button" className="notes-graph-control" onClick={() => controlsRef.current.zoomOut?.()} aria-label="Zoom out" title="Zoom out">
                <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round">
                  <path d="M3 8h10" />
                </svg>
              </button>
              <button type="button" className="notes-graph-control" onClick={() => controlsRef.current.fit?.()} aria-label="Fit graph to view" title="Fit to view">
                <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M2 6V2h4M10 2h4v4M14 10v4h-4M6 14H2v-4" />
                </svg>
              </button>
              {canFullscreen && (
                <button
                  type="button"
                  className="notes-graph-control"
                  onClick={toggleFullscreen}
                  aria-label={isFullscreen ? 'Exit full screen' : 'Full screen'}
                  title={isFullscreen ? 'Exit full screen' : 'Full screen'}
                >
                  <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
                    {isFullscreen ? <path d="M6 2v4H2M10 2v4h4M14 10h-4v4M2 10h4v4" /> : <path d="M9.5 2H14v4.5M14 2 9 7M6.5 14H2V9.5M2 14l5-5" />}
                  </svg>
                </button>
              )}
            </div>
          )}

          {graph && <div className={`notes-graph-hint ${(active && showControlsHint) || (!active && (nudge || isCoarse)) ? 'notes-graph-hint--show' : ''}`}>{hint}</div>}
        </div>
        {graph && (
          <div className="notes-graph-footer">
            <span>
              {noteCount} notes · {linkCount} links
            </span>
            {!isCoarse && <span className="notes-graph-footer-hint">Drag the dots around</span>}
          </div>
        )}
      </div>
    </div>
  );
}

export default NotesGraph;
